// Tenant guard. "Find Reservations tool" is SHARED by every client, so it must be told whose data this is: the account
// id from the conversation, or the calling workflow (the database maps it to its client). It never falls
// back to a default: that is how a booking would land in the wrong hotel.
const inp = $input.first().json || {};
let d = inp;
if (typeof inp.query === 'string') { try { d = JSON.parse(inp.query); } catch (e) { d = inp; } }
else if (inp.query && typeof inp.query === 'object') { d = inp.query; }
const acct = String(d.accountId ?? '').trim(), wf = String(d.workflowId ?? '').trim();
if (!/^\d+$/.test(acct) && !wf) throw new Error('Find Reservations tool was called without accountId or workflowId - refusing to guess whose data to use.');
return [{ json: Object.assign({}, d, { accountId: acct, workflowId: wf }) }];

const j = $input.first().json || {};
if (j.error) return [{ json: { reservations: [], message: 'Reservations cannot be looked up right now. Do not guess; offer to connect the guest with a person.' } }];
return [{ json: j.r || { reservations: [], message: 'No reservation matches those details.' } }];
